attempts = {}
def download(image_id):
    attempts[image_id] = attempts.get(image_id, 0) + 1
    if image_id == 'retry' and attempts[image_id] < 3:
        raise TransientDownloadError('temporary')
    return image_id
def sanitize(raw):
    if raw == 'bad':
        raise RuntimeError('invalid image')
    return raw
class Model:
    def __init__(self):
        self.calls = []
    def predict(self, value):
        self.calls.append(value)
        return value.upper()
model = Model()
service = ImagePredictionService(download, sanitize, {'m': model}, capacity=2, max_retries=2)
assert service.predict('retry', 'm') == 'RETRY'
assert attempts['retry'] == 3
try:
    service.predict('bad', 'm')
except RuntimeError:
    pass
else:
    raise AssertionError('sanitizer errors must propagate')
assert attempts['bad'] == 1
assert service.predict('one', 'm') == 'ONE'
assert service.predict('retry', 'm') == 'RETRY'
assert service.predict('two', 'm') == 'TWO'
assert service.predict('one', 'm') == 'ONE'
assert attempts['one'] == 2
assert attempts['retry'] == 3

def must_raise(call, error=ValueError):
    try:
        call()
    except error:
        return
    raise AssertionError(f'expected {error.__name__}')
must_raise(lambda: ImagePredictionService(lambda x: x, lambda x: x, {}, 0))
must_raise(lambda: ImagePredictionService(lambda x: x, lambda x: x, {}, 1, -1))
def broken_download(_):
    raise TransientDownloadError('down')
service = ImagePredictionService(broken_download, lambda x: x, {'m': object()}, 1, max_retries=1)
must_raise(lambda: service.predict('x', 'm'), TransientDownloadError)
must_raise(lambda: service.predict('x', 'missing'))
class BadModel:
    def predict(self, _):
        raise RuntimeError('model failed')
model_service = ImagePredictionService(lambda x: x, lambda x: x, {'m': BadModel()}, 1)
must_raise(lambda: model_service.predict('x', 'm'), RuntimeError)
